import * as React from "react"
import { Link, type PageProps } from "gatsby"

import { Layout } from "../components/layout"
import { Seo } from "../components/seo"
import { useTranslation } from '../utils/i18n'

function excerpt(html: string, limit: number) {
  const text = html.replace(/<[^>]+>/g, '');
  return text.length > limit ? text.slice(0, limit) + '...' : text;
}

export interface Post {
  id: string;
  excerpt: string;
  html: string;
  fields: { slug: string; };
  frontmatter: { date: string; title: string };
}


function ListRoute({ location, pageContext }: PageProps<unknown, {
  postCategory: string;
  posts: Post[];
}>) {
  const { t, i18n } = useTranslation()
  return (
    <Layout location={location}>
      <h3> {t(`${pageContext.postCategory}-list`)} </h3>
      <ul>
        {pageContext.posts.map(post => (
          <li key={post.fields.slug}>
            <Link to={post.fields.slug}>
              {new Intl.DateTimeFormat(i18n.language, {
                dateStyle: 'full',
              }).format(new Date(post.frontmatter.date))}
            </Link>
             {' '}
             {post.frontmatter.title || excerpt(post.html, 25)}
          </li>
        ))}
      </ul>
    </Layout>
  )
}

export default ListRoute

export function Head() {
  return <Seo title="All posts" />
}
